import { Columns2, Rows2, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import type { LayoutState, NestedSplit, Pane, TerminalSession, TerminalTab } from "../lib/types";
import { TabBar } from "./TabBar";
import { TerminalPane } from "./TerminalPane";
import { IconButton } from "./ui/IconButton";

type TerminalSplitViewProps = {
  layout: LayoutState;
  sessions: Record<string, TerminalSession>;
  onActivateTab?: (tabId: string) => void;
  onCloseTab?: (tabId: string) => void;
  onAddTab?: () => void;
  onSplitRight?: () => void;
  onSplitDown?: () => void;
  onUnsplit?: () => void;
  onTitleChange?: (tabId: string, title: string) => void;
};

const MIN_PANE_SIZE_PX = 160;

export function TerminalSplitView({
  layout,
  sessions,
  onActivateTab = () => undefined,
  onCloseTab = () => undefined,
  onAddTab = () => undefined,
  onSplitRight = () => undefined,
  onSplitDown = () => undefined,
  onUnsplit = () => undefined,
  onTitleChange = () => undefined,
}: TerminalSplitViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const draggingRef = useRef(false);
  const [splitRatio, setSplitRatio] = useState(0.5);
  const primaryTab = layout.tabs.find((tab) => tab.id === layout.primaryTabId) ?? null;
  const secondaryTab = layout.split !== "none"
    ? layout.tabs.find((tab) => tab.id === layout.secondaryTabId) ?? null
    : null;
  const primarySession = primaryTab ? sessions[primaryTab.sessionId] ?? null : null;
  const secondarySession = secondaryTab ? sessions[secondaryTab.sessionId] ?? null : null;
  const primaryPane: Pane | null = primaryTab ? { id: "primary", tabId: primaryTab.id } : null;
  const secondaryPane: Pane | null = secondaryTab ? { id: "secondary", tabId: secondaryTab.id } : null;
  const splitActive = layout.split !== "none" && Boolean(secondaryTab && secondaryPane && secondarySession);

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      if (!draggingRef.current || layout.split === "none") return;
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;
      const size = layout.split === "horizontal" ? rect.width : rect.height;
      if (size <= 0) return;
      const pointer = layout.split === "horizontal" ? event.clientX - rect.left : event.clientY - rect.top;
      const minRatio = Math.min(0.5, MIN_PANE_SIZE_PX / size);
      const nextRatio = Math.min(1 - minRatio, Math.max(minRatio, pointer / size));
      setSplitRatio(nextRatio);
    };

    const finishDrag = () => {
      if (!draggingRef.current) return;
      draggingRef.current = false;
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, [layout.split]);

  if (!primaryTab || !primaryPane || !primarySession) {
    return <div className="relative flex-1 overflow-hidden bg-terminal" data-testid="terminal-layout" data-split="none" />;
  }

  const primaryBasis = splitActive ? formatRatioPercent(splitRatio) : undefined;
  const secondaryBasis = splitActive ? formatRatioPercent(1 - splitRatio) : undefined;
  const paneStyle = (basis: string | undefined) =>
    basis
      ? { flexBasis: basis, flexGrow: 0, flexShrink: 0 }
      : undefined;

  const startDividerDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    draggingRef.current = true;
    document.body.style.cursor = layout.split === "horizontal" ? "col-resize" : "row-resize";
  };

  const paneActions = (
    <>
      <IconButton label="Split pane right" size="sm" onClick={onSplitRight}>
        <Columns2 className="size-3.5" />
      </IconButton>
      <IconButton label="Split pane down" size="sm" onClick={onSplitDown}>
        <Rows2 className="size-3.5" />
      </IconButton>
      {splitActive ? (
        <IconButton label="Close split view" size="sm" onClick={onUnsplit}>
          <X className="size-3.5" />
        </IconButton>
      ) : null}
    </>
  );

  return (
    <div
      ref={containerRef}
      className={`relative flex flex-1 overflow-hidden bg-terminal ${
        layout.split === "horizontal" ? "flex-row" : layout.split === "vertical" ? "flex-col" : ""
      }`}
      data-testid="terminal-layout"
      data-split={layout.split}
    >
      <TerminalPaneFrame
        testId="primary-pane"
        pane={primaryPane}
        tab={primaryTab}
        tabs={layout.tabs}
        session={primarySession}
        activeTabId={primaryTab.id}
        style={paneStyle(primaryBasis)}
        actions={paneActions}
        showAdd
        nestedSplit={
          layout.nestedSplit && layout.nestedSplit.tabId === primaryTab.id
            ? layout.nestedSplit
            : null
        }
        onActivateTab={onActivateTab}
        onCloseTab={onCloseTab}
        onAddTab={onAddTab}
        onTitleChange={(title) => onTitleChange(primaryTab.id, title)}
      />

      {splitActive && secondaryTab && secondaryPane && secondarySession ? (
        <>
          <div
            role="separator"
            aria-label="Resize terminal panes"
            aria-orientation={layout.split === "horizontal" ? "vertical" : "horizontal"}
            aria-valuemin={MIN_PANE_SIZE_PX}
            aria-valuenow={Math.round(splitRatio * 100)}
            data-divider-hit-target="true"
            onPointerDown={startDividerDrag}
            className={`no-drag absolute z-30 flex touch-none items-center justify-center ${
              layout.split === "horizontal"
                ? "inset-y-0 w-1.5 -translate-x-1/2 cursor-col-resize"
                : "inset-x-0 h-1.5 -translate-y-1/2 cursor-row-resize"
            }`}
            style={layout.split === "horizontal" ? { left: formatRatioPercent(splitRatio) } : { top: formatRatioPercent(splitRatio) }}
          >
            <span
              data-testid="split-divider-line"
              className={layout.split === "horizontal" ? "h-full w-px bg-border" : "h-px w-full bg-border"}
            />
          </div>
          <TerminalPaneFrame
            testId="secondary-pane"
            pane={secondaryPane}
            tab={secondaryTab}
            tabs={[secondaryTab]}
            session={secondarySession}
            activeTabId={secondaryTab.id}
            style={paneStyle(secondaryBasis)}
            actions={paneActions}
            showAdd={false}
            onActivateTab={onActivateTab}
            onCloseTab={onCloseTab}
            onAddTab={onAddTab}
            onTitleChange={(title) => onTitleChange(secondaryTab.id, title)}
          />
        </>
      ) : null}
    </div>
  );
}

type TerminalPaneFrameProps = {
  testId: string;
  pane: Pane;
  tab: TerminalTab;
  tabs: TerminalTab[];
  session: TerminalSession;
  activeTabId: string;
  style?: React.CSSProperties;
  actions: React.ReactNode;
  showAdd: boolean;
  nestedSplit?: NestedSplit | null;
  onActivateTab: (tabId: string) => void;
  onCloseTab: (tabId: string) => void;
  onAddTab: () => void;
  onTitleChange?: (title: string) => void;
};

function TerminalPaneFrame({
  testId,
  pane,
  tab,
  tabs,
  session,
  activeTabId,
  style,
  actions,
  showAdd,
  nestedSplit,
  onActivateTab,
  onCloseTab,
  onAddTab,
  onTitleChange,
}: TerminalPaneFrameProps) {
  return (
    <div
      className="relative flex min-h-0 min-w-0 flex-col overflow-hidden bg-terminal"
      data-testid={testId}
      data-pane-id={pane.id}
      style={style}
    >
      <TabBar
        tabs={tabs}
        activeTabId={activeTabId}
        onActivate={onActivateTab}
        onClose={onCloseTab}
        onAdd={onAddTab}
        actions={actions}
        showAdd={showAdd}
      />
      <div
        className={`min-h-0 flex-1 overflow-hidden ${
          nestedSplit ? `flex ${nestedSplit.orientation === "vertical" ? "flex-col" : "flex-row"}` : ""
        }`}
      >
        <div className="min-h-0 min-w-0 flex-1 overflow-hidden">
          <TerminalPane
            key={`${pane.id}:${tab.id}`}
            session={session}
            active
            onTitleChange={onTitleChange}
          />
        </div>
        {nestedSplit ? (
          <div
            data-testid={`nested-${pane.id}-pane`}
            data-pane-id={`nested-${pane.id}`}
            className="min-h-0 min-w-0 flex-1 overflow-hidden"
          >
            <TerminalPane
              key={`nested-${pane.id}:${tab.id}`}
              session={session}
              active
              onTitleChange={onTitleChange}
            />
          </div>
        ) : null}
      </div>
    </div>
  );
}

function formatRatioPercent(ratio: number) {
  return `${Number((ratio * 100).toFixed(4))}%`;
}

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { LayoutState, SplitMode, TerminalSession, TerminalTab } from "../lib/types";
import { TerminalSplitView } from "./TerminalSplitView";

vi.mock("./TerminalPane", () => ({
  TerminalPane: ({ session }: { session: TerminalSession }) => (
    <div data-testid="terminal-pane" data-backend-session-id={session.backendSessionId ?? ""} />
  ),
}));

afterEach(cleanup);

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

function session(id: string, backendSessionId: string): TerminalSession {
  return {
    id,
    cwd: "/repo",
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: "main" },
    backendSessionId,
    lifecycle: "working",
  };
}

function splitFixture(split: Exclude<SplitMode, "none">) {
  const primary = tab("tab-1", "session-1");
  const secondary = tab("tab-2", "session-2");
  const layout: LayoutState = {
    tabs: [primary, secondary],
    primaryTabId: primary.id,
    secondaryTabId: secondary.id,
    split,
    nestedSplit: null,
  };
  const sessions = {
    "session-1": session("session-1", "backend-1"),
    "session-2": session("session-2", "backend-2"),
  };
  return { layout, sessions };
}

function mockLayoutBounds(width = 800, height = 800) {
  const layout = screen.getByTestId("terminal-layout");
  vi.spyOn(layout, "getBoundingClientRect").mockReturnValue({
    width,
    height,
    left: 0,
    top: 0,
    right: width,
    bottom: height,
    x: 0,
    y: 0,
    toJSON: () => ({}),
  });
  return layout;
}

describe("TerminalSplitView", () => {
  it("renders a mirror pane immediately for a single-tab split state", () => {
    const primary = tab("tab-1", "session-1");
    const layout: LayoutState = {
      tabs: [primary],
      primaryTabId: primary.id,
      secondaryTabId: primary.id,
      split: "horizontal",
      nestedSplit: null,
    };
    const sessions = { "session-1": session("session-1", "backend-1") };

    render(<TerminalSplitView layout={layout} sessions={sessions} />);

    expect(screen.getByTestId("primary-pane")).toBeInTheDocument();
    expect(screen.getByTestId("secondary-pane")).toBeInTheDocument();
    expect(screen.getAllByTestId("terminal-pane")).toHaveLength(2);
    expect(screen.getAllByTestId("terminal-pane")[0]).toHaveAttribute("data-backend-session-id", "backend-1");
    expect(screen.getAllByTestId("terminal-pane")[1]).toHaveAttribute("data-backend-session-id", "backend-1");
  });

  it("owns split controls inside each terminal pane and dispatches pane actions", () => {
    const primary = tab("tab-1", "session-1");
    const layout: LayoutState = {
      tabs: [primary],
      primaryTabId: primary.id,
      secondaryTabId: null,
      split: "none",
      nestedSplit: null,
    };
    const sessions = { "session-1": session("session-1", "backend-1") };
    const onSplitRight = vi.fn();
    const onSplitDown = vi.fn();
    const onUnsplit = vi.fn();

    render(
      <TerminalSplitView
        {...({ layout, sessions, onSplitRight, onSplitDown, onUnsplit } as any)}
      />,
    );

    const pane = screen.getByTestId("primary-pane");
    const splitRight = screen.getByRole("button", { name: "Split pane right" });
    const splitDown = screen.getByRole("button", { name: "Split pane down" });
    expect(pane).toContainElement(splitRight);
    expect(pane).toContainElement(splitDown);
    fireEvent.click(splitRight);
    fireEvent.click(splitDown);
    expect(onSplitRight).toHaveBeenCalledOnce();
    expect(onSplitDown).toHaveBeenCalledOnce();
    expect(screen.queryByRole("button", { name: "Interrupt terminal" })).not.toBeInTheDocument();
    expect(onUnsplit).not.toHaveBeenCalled();
  });

  it("renders a close split control in each pane and routes it", () => {
    const { layout, sessions } = splitFixture("horizontal");
    const onUnsplit = vi.fn();

    render(<TerminalSplitView layout={layout} sessions={sessions} onUnsplit={onUnsplit} />);

    const [primaryClose, secondaryClose] = screen.getAllByRole("button", { name: "Close split view" });
    expect(screen.getByTestId("primary-pane")).toContainElement(primaryClose);
    expect(screen.getByTestId("secondary-pane")).toContainElement(secondaryClose);

    fireEvent.click(secondaryClose);
    expect(onUnsplit).toHaveBeenCalledOnce();
  });

  it("renders an orthogonal nested split without replacing the outer split", () => {
    const { layout, sessions } = splitFixture("horizontal");
    layout.nestedSplit = { orientation: "vertical", tabId: layout.primaryTabId! };

    render(<TerminalSplitView layout={layout} sessions={sessions} />);

    expect(screen.getByTestId("primary-pane")).toBeInTheDocument();
    expect(screen.getByTestId("secondary-pane")).toBeInTheDocument();
    expect(screen.getByTestId("nested-primary-pane")).toBeInTheDocument();
    expect(screen.getAllByTestId("terminal-pane")).toHaveLength(3);
    expect(screen.getByTestId("nested-primary-pane")).toContainElement(
      screen.getAllByTestId("terminal-pane")[1],
    );
  });

  it("renders one visible pixel inside the larger split resize hit target", () => {
    const { layout, sessions } = splitFixture("horizontal");
    render(<TerminalSplitView layout={layout} sessions={sessions} />);

    const divider = screen.getByRole("separator", { name: "Resize terminal panes" });
    expect(divider).toHaveAttribute("data-divider-hit-target", "true");
    expect(screen.getByTestId("split-divider-line")).toHaveClass("w-px");
  });

  it("drags a horizontal split divider and clamps both panes to the minimum size", () => {
    const { layout, sessions } = splitFixture("horizontal");
    render(<TerminalSplitView layout={layout} sessions={sessions} />);
    mockLayoutBounds();

    const divider = screen.getByRole("separator", { name: "Resize terminal panes" });
    const primaryPane = screen.getByTestId("primary-pane");
    const secondaryPane = screen.getByTestId("secondary-pane");
    expect(divider).toHaveAttribute("aria-orientation", "vertical");

    fireEvent.pointerDown(divider, { clientX: 400, clientY: 400 });
    fireEvent.pointerMove(window, { clientX: 80, clientY: 400 });

    expect(primaryPane).toHaveStyle({ flexBasis: "20%" });
    expect(secondaryPane).toHaveStyle({ flexBasis: "80%" });
    fireEvent.pointerUp(window);
  });

  it("drags a vertical split divider and clamps both panes to the minimum size", () => {
    const { layout, sessions } = splitFixture("vertical");
    render(<TerminalSplitView layout={layout} sessions={sessions} />);
    mockLayoutBounds();

    const divider = screen.getByRole("separator", { name: "Resize terminal panes" });
    const primaryPane = screen.getByTestId("primary-pane");
    const secondaryPane = screen.getByTestId("secondary-pane");
    expect(divider).toHaveAttribute("aria-orientation", "horizontal");

    fireEvent.pointerDown(divider, { clientX: 400, clientY: 400 });
    fireEvent.pointerMove(window, { clientX: 400, clientY: 760 });

    expect(primaryPane).toHaveStyle({ flexBasis: "80%" });
    expect(secondaryPane).toHaveStyle({ flexBasis: "20%" });
    fireEvent.pointerUp(window);
  });
});

import { describe, expect, it } from "vitest";

import type { TerminalTab } from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

describe("layoutReducer", () => {
  it("enables a single-tab mirror split without adding another logical tab", () => {
    const primary = tab("tab-1", "session-1");
    const state = createLayoutState([primary], primary.id);

    const next = layoutReducer(state, {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: primary.id,
    });

    expect(next.tabs).toEqual([primary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBe(primary.id);
    expect(next.split).toBe("horizontal");
  });

  it("uses an existing other tab as the secondary pane when available", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const state = createLayoutState([primary, secondary], primary.id);

    const next = layoutReducer(state, {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    expect(next.tabs).toEqual([primary, secondary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBe(secondary.id);
    expect(next.split).toBe("horizontal");
  });

  it("keeps a horizontal split when adding a vertical nested split", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const horizontal = layoutReducer(createLayoutState([primary, secondary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    const nested = layoutReducer(horizontal, {
      type: "ENABLE_SPLIT",
      orientation: "vertical",
      secondaryTabId: primary.id,
    });

    expect(nested).toMatchObject({
      primaryTabId: primary.id,
      secondaryTabId: secondary.id,
      split: "horizontal",
      nestedSplit: {
        orientation: "vertical",
        tabId: primary.id,
      },
    });
  });

  it("rotates split orientation without changing tab identity", () => {
    const primary = tab("tab-1", "session-1");
    const split = layoutReducer(createLayoutState([primary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: primary.id,
    });

    const rotated = layoutReducer(split, { type: "ROTATE_SPLIT" });

    expect(rotated.split).toBe("vertical");
    expect(rotated.tabs).toEqual(split.tabs);
    expect(rotated.primaryTabId).toBe(split.primaryTabId);
    expect(rotated.secondaryTabId).toBe(split.secondaryTabId);
  });

  it("applies the last-tab-close replacement policy atomically", () => {
    const primary = tab("tab-1", "session-1");
    const replacement = tab("tab-2", "session-2");
    const state = createLayoutState([primary], primary.id);

    const next = layoutReducer(state, {
      type: "CLOSE_TAB",
      tabId: primary.id,
      replacementTab: replacement,
    });

    expect(next.tabs).toEqual([replacement]);
    expect(next.primaryTabId).toBe(replacement.id);
    expect(next.secondaryTabId).toBeNull();
    expect(next.split).toBe("none");
  });

  it("never leaves stale split ids when the secondary tab closes", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const split = layoutReducer(createLayoutState([primary, secondary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    const next = layoutReducer(split, { type: "CLOSE_TAB", tabId: secondary.id });

    expect(next.tabs).toEqual([primary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBeNull();
    expect(next.split).toBe("none");
  });
});

