  | "terminal.splitRight"
  | "terminal.splitDown"
  | "terminal.unsplit"
  | "sidebar.left.toggle"
  | "commandPalette.open";

type ShortcutBinding = {
  key: string;
  mod?: boolean;
  control?: boolean;
  alt?: boolean;
  shift?: boolean;
};

export type ShortcutDefinition = {
